class Solution:
    def mergeKLists(self, lists: List[Optional[ListNode]]) -> Optional[ListNode]:
        if not lists:
            return None
        def merge_two(a, b):
            dummy = ListNode(0)
            tail = dummy
            while a and b:
                if a.val <= b.val:
                    tail.next = a
                    a = a.next
                else:
                    tail.next = b
                    b = b.next
                tail = tail.next
            tail.next = a if a else b
            return dummy.next
        def merge_range(left, right):
            if left == right:
                return lists[left]
            mid = (left + right) // 2
            l = merge_range(left, mid)
            r = merge_range(mid + 1, right)
            return merge_two(l, r)
        return merge_range(0, len(lists) - 1)
